class Solution {
public:
    double maximumAverageSubtree(TreeNode* root) {
        double max_avg = 0.0;

        auto dfs = [&](auto& self, TreeNode* node) -> pair<long long, int> {
            if (!node) return {0, 0};
            auto [l_sum, l_cnt] = self(self, node->left);
            auto [r_sum, r_cnt] = self(self, node->right);
            long long tot_sum = l_sum + r_sum + node->val;
            int tot_cnt = l_cnt + r_cnt + 1;
            max_avg = max(max_avg, (double)tot_sum / tot_cnt);
            return {tot_sum, tot_cnt};
        };

        dfs(dfs, root);
        return max_avg;
    }
};

class Solution {
    double maxAvg = 0.0;

    long[] dfs(TreeNode node) {
        if (node == null) return new long[]{0, 0};
        long[] left = dfs(node.left);
        long[] right = dfs(node.right);
        long totSum = left[0] + right[0] + node.val;
        long totCnt = left[1] + right[1] + 1;
        maxAvg = Math.max(maxAvg, (double)totSum / totCnt);
        return new long[]{totSum, totCnt};
    }

    public double maximumAverageSubtree(TreeNode root) {
        maxAvg = 0.0;
        dfs(root);
        return maxAvg;
    }
}

var maximumAverageSubtree = function(root) {
    let maxAvg = 0.0;

    const dfs = (node) => {
        if (!node) return [0, 0];
        const [lSum, lCnt] = dfs(node.left);
        const [rSum, rCnt] = dfs(node.right);
        const totSum = lSum + rSum + node.val;
        const totCnt = lCnt + rCnt + 1;
        maxAvg = Math.max(maxAvg, totSum / totCnt);
        return [totSum, totCnt];
    };

    dfs(root);
    return maxAvg;
};
